<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave } from 'vue-router'
import { useResearchStore } from '../stores/research'
import type { Slide,Deck } from '../types'
import Frame from '../components/AppFrame.vue'
import Sidebar from '../components/AppSidebar.vue'
import Icon from '../components/AppIcon.vue'
import SlidePreview from '../components/SlidePreview.vue'
import ResearchNotesPanel from '../components/ResearchNotesPanel.vue'
const store=useResearchStore(),route=useRoute(),router=useRouter(),index=ref(0),draft=ref<Slide[]>([]),dirty=ref(false),exporting=ref(false),filter=ref('')
const deck=computed(()=>store.decks.find(d=>d.id===route.params.id)),slide=computed(()=>draft.value[index.value])
watch(deck,value=>{draft.value=value?JSON.parse(JSON.stringify(value.slides)):[];index.value=0;dirty.value=false},{immediate:true})
async function create(){const d=await store.createDeck();if(d)router.push('/artifacts/'+d.id)}
function remove(item:Deck){if(window.confirm('确定删除汇报「'+item.title+'」吗？此操作仅删除当前版本的本地草稿，已导出的 PPTX 文件不受影响。'))store.deleteDeck(item.id)}
function save(){if(!deck.value)return;const result:Deck={...deck.value,id:crypto.randomUUID(),version:deck.value.version+1,createdAt:new Date().toISOString(),slides:JSON.parse(JSON.stringify(draft.value))};store.decks.unshift(result);store.saveDecks();dirty.value=false;router.replace('/artifacts/'+result.id);store.notify('已保存为新版本，原版本仍在成果中心。')}
async function download(){if(!deck.value||exporting.value)return;exporting.value=true;try{const {exportPresentation}=await import('../lib/presentation');await exportPresentation({...deck.value,slides:draft.value});store.notify('PPTX 已导出，标题与正文可在PowerPoint 等软件中编辑。')}catch{store.notify('PPTX 导出失败，请重试；草稿仍保留。')}finally{exporting.value=false}}
function move(direction:number){const target=index.value+direction;if(target<0||target>=draft.value.length)return;[draft.value[index.value],draft.value[target]]=[draft.value[target]!,draft.value[index.value]!];index.value=target;dirty.value=true}
onBeforeRouteLeave(()=>!dirty.value||window.confirm('当前页有未保存的汇报修改，确定离开吗？'))
</script>
<template>
  <div v-if="deck&&slide" class="app-shell"><Sidebar/><main id="main-content" class="deck-editor"><header class="deck-editor-header"><button class="icon-button" aria-label="返回成果中心" @click="router.push('/artifacts')"><Icon name="ArrowLeft"/></button><div><strong>{{deck.title}}</strong><span>汇报草稿 · v{{deck.version}} · {{draft.length}} 页<span v-if="dirty"> · 有未保存修改</span></span></div><button class="secondary-button" :disabled="!dirty" @click="save"><Icon name="CheckCheck" :size="15"/>保存新版本</button><button class="primary-button" :disabled="exporting" :aria-busy="exporting" @click="download"><Icon :name="exporting?'LoaderCircle':'Download'" :class="{spin:exporting}" :size="16"/>导出 PPTX</button></header><div class="deck-editor-body"><nav class="slide-thumbnails" aria-label="幻灯片列表"><button v-for="(item,i) in draft" :key="item.id" :class="{active:i===index}" :aria-label="`编辑第 ${i+1} 页：${item.title}`" @click="index=i"><span>{{String(i+1).padStart(2,'0')}}</span><SlidePreview :slide="item" :index="i" thumbnail/></button></nav><section class="slide-editing-area"><div class="slide-editing-title"><span>第 {{index+1}} 页<span class="context-dot">·</span>预览</span><div><button class="icon-button" aria-label="将当前页前移" :disabled="index===0" @click="move(-1)"><Icon name="ArrowLeft" :size="15"/></button><button class="icon-button" aria-label="将当前页后移" :disabled="index===draft.length-1" @click="move(1)"><Icon name="ArrowRight" :size="15"/></button></div></div><SlidePreview :slide="slide" :index="index"/><p class="slide-preview-caption"><Icon name="CircleHelp" :size="14"/>浏览器预览用于内容审阅，最终排版请以导出 PPTX 为准。</p><div class="slide-fields"><label>页面标题<input v-model="slide.title" maxlength="180" @input="dirty=true"/></label><label>页面内容<textarea v-model="slide.body" rows="5" maxlength="1800" @input="dirty=true"></textarea></label></div></section></div></main></div>
  <Frame v-else title="成果中心" subtitle="把探索留下来，把思考表达出去。你的研究成果，都有迹可循。" eyebrow="FROM IDEAS TO SOMETHING TANGIBLE"><ResearchNotesPanel all-spaces/><div class="artifacts-toolbar"><div class="segmented-control"><button class="active"><Icon name="Presentation" :size="15"/>汇报草稿<span>{{store.decks.length}}</span></button></div><label class="search-field"><Icon name="Search" :size="16"/><input v-model="filter" aria-label="搜索研究成果" placeholder="搜索成果名称"/></label><button class="primary-button" :disabled="store.generatingDeck" @click="create"><Icon name="Plus" :size="16"/>从当前材料创建汇报</button></div><div v-if="store.decks.filter(d=>d.title.toLowerCase().includes(filter.toLowerCase())).length" class="artifact-grid"><article v-for="item in store.decks.filter(d=>d.title.toLowerCase().includes(filter.toLowerCase()))" :key="item.id" class="artifact-card artifact-card-managed"><RouterLink :to="'/artifacts/'+item.id" class="artifact-open"><SlidePreview :slide="item.slides[0]!" :index="0" thumbnail/><div><span class="artifact-type"><Icon name="Presentation" :size="13"/>PPTX 草稿 · v{{item.version}}</span><h2>{{item.title}}</h2><p>{{item.slides.length}} 页 · {{new Date(item.createdAt).toLocaleDateString('zh-CN')}}<Icon name="ArrowUpRight" :size="16"/></p></div></RouterLink><button class="icon-button artifact-delete" :aria-label="'删除汇报：'+item.title" title="删除汇报" @click="remove(item)"><Icon name="Trash2" :size="16"/></button></article></div><div v-else class="artifacts-empty"><div class="empty-slides"><div></div><div></div><span><Icon name="Presentation" :size="36"/></span></div><span class="eyebrow">YOUR IDEAS DESERVE A STAGE</span><h2>{{filter?'还没有匹配的成果':'让这次探索，有一份清晰的表达。'}}</h2><p>选择论文，组织阅读脉络，生成一份可以逐页推敲的汇报。<br>当前可生成本地汇报草稿，并导出真实的可编辑 PPTX。</p><button class="primary-button" :disabled="store.generatingDeck" @click="create">使用当前材料创建汇报<Icon name="ArrowRight" :size="16"/></button></div><div class="inline-info"><Icon name="ShieldCheck" :size="17"/><p>草稿仅保存在当前浏览器中。清理浏览器数据会移除本地成果，请及时导出需要保留的内容。</p></div></Frame>
</template>

<style scoped>
.artifact-card-managed{position:relative}.artifact-open{display:block;color:inherit;text-decoration:none}.artifact-open>div:last-child{padding:20px}.artifact-open>:deep(.slide-preview){border-radius:0;box-shadow:none}.artifact-delete{position:absolute;right:12px;top:12px;background:var(--surface-raised);border:1px solid var(--border);border-radius:8px}.artifact-delete:hover{color:var(--purple-deep);background:var(--purple-soft)}
</style>
